curl --request PUT \
    --url https://ip_address:9440/api/nutanix/v3/categories/{name} \
    --header 'Accept: application/json' \
    --header 'Authorization: Basic <basic_auth_token>' \
    --header 'Content-Type: application/json' \
    --data '{
    "capabilities": {
        "cardinality": 0
    },
    "description": "string",
    "name": "string"
}'

wget --quiet \
    --method PUT \
    --header 'Accept: application/json' \
    --header 'Authorization: Basic <basic_auth_token>' \
    --header 'Content-Type: application/json' \
    --body-data '{
    "capabilities": {
        "cardinality": 0
    },
    "description": "string",
    "name": "string"
}' \
    --output-document \
    - https://ip_address:9440/api/nutanix/v3/categories/{name}

import http.client

conn = http.client.HTTPSConnection("ip_address:9440")

headers = {
    "Accept": "application/json",
    "Authorization": "Basic <basic_auth_token>",
    "Content-Type": "application/json"
}

payload =  """{
    "capabilities": {
        "cardinality": 0
    },
    "description": "string",
    "name": "string"
}"""

conn.request("PUT","/api/nutanix/v3/categories/{name}", payload, headers)

res = conn.getresponse()
data = res.read()

print(data.decode("utf-8"))

package main

import (
	"fmt"
	"strings"
	"net/http"
	"io"
)

func main() {

	url := "https://ip_address:9440/api/nutanix/v3/categories/{name}"

	payload :=  strings.NewReader(`{"capabilities": {"cardinality": 0}, "description": "string", "name": "string"}`)
	req, err := http.NewRequest("PUT", url, payload)
	if err != nil {
		fmt.Println("Error creating request:", err)
